import { AMBIENT_POINTS, PITCH_STEP, restorePoints, pointGeometry, movePoint, pointPan, midiLabel } from './ambient-points.mjs?v=hushfield-1';
import { ambientChord } from './ambient-settings.mjs?v=hushfield-1';
export function setupAmbientPoints({getState,getStatus,onChange}){
 const canvas=document.getElementById('ambientCanvas'),stage=document.getElementById('ambientStage'),layer=document.createElement('div'),buttons=[],drags=new Map();
 layer.className='ambient-points';layer.setAttribute('role','group');layer.setAttribute('aria-label','Drag chord voices: up and down for pitch, left and right for stereo position');stage.append(layer);
 const guide=document.createElement('div');guide.className='ambient-gesture-guide';guide.setAttribute('aria-hidden','true');guide.innerHTML='<span>HIGHER · SCALE STEPS</span><span>LEFT ← STEREO → RIGHT</span>';stage.append(guide);
 const announce=(type,index,cancelled=false)=>layer.dispatchEvent(new CustomEvent('hushfield:'+type,{bubbles:true,detail:{label:'Foundation voice '+(index+1),source:'voice-dot',cancelled}}));
 let lastTime=0,lastReduced=false;
 function change(index,x,y){const state=getState(),points=restorePoints(state.points);points[index]=movePoint(points[index],x,y);state.points=points;onChange();}
 function release(button,event){if(!drags.has(event.pointerId))return;const drag=drags.get(event.pointerId);if(event.type==='pointercancel'){getState().points=drag.points;onChange();}drags.delete(event.pointerId);button.classList.remove('dragging');button.setAttribute('aria-pressed','false');stage.classList.toggle('editing-voice',drags.size>0);announce('editend',drag.index,event.type==='pointercancel');}
 for(let index=0;index<4;index++){
  const button=document.createElement('button');button.type='button';button.className='ambient-point';button.dataset.voice=String(index);button.setAttribute('aria-pressed','false');button.innerHTML='<span class="ambient-dot" aria-hidden="true"></span><span class="ambient-point-note" aria-hidden="true"></span>';layer.append(button);buttons.push(button);
  button.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();const rect=canvas.getBoundingClientRect(),point=pointGeometry(getState().points[index],index,lastTime,lastReduced,false,rect.width,rect.height);announce('editstart',index);stage.classList.add('editing-voice');drags.set(event.pointerId,{index,points:restorePoints(getState().points),dx:event.clientX-rect.left-point.x*rect.width,dy:event.clientY-rect.top-point.y*rect.height});button.setPointerCapture(event.pointerId);button.classList.add('dragging');button.setAttribute('aria-pressed','true');});
  button.addEventListener('pointermove',event=>{const drag=drags.get(event.pointerId);if(!drag||drag.index!==index)return;event.preventDefault();const rect=canvas.getBoundingClientRect();if(rect.width&&rect.height)change(index,(event.clientX-rect.left-drag.dx)/rect.width,(event.clientY-rect.top-drag.dy)/rect.height);});
  for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,event=>release(button,event));
  button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(event.key))return;event.preventDefault();announce('editstart',index);const point=getState().points[index];if(event.key==='Home'){change(index,AMBIENT_POINTS[index].x,AMBIENT_POINTS[index].y);announce('editend',index);return;}change(index,point.x+(event.key==='ArrowRight'?.025:event.key==='ArrowLeft'?-.025:0),point.y+(event.key==='ArrowDown'?PITCH_STEP:event.key==='ArrowUp'?-PITCH_STEP:0));announce('editend',index);});
 }
 const reset=document.createElement('button');reset.id='resetAmbientPoints';reset.type='button';reset.textContent='Reset dots';reset.addEventListener('click',()=>{announce('editstart',0);getState().points=restorePoints();onChange();announce('editend',0);});document.getElementById('ambientSeed').before(reset);
 function render(w,h,time,level,reduced=false){lastTime=time;lastReduced=reduced;const state=getState(),notes=ambientChord(state,getStatus().degree||0);return state.points.map((point,index)=>{const dragging=Array.from(drags.values()).some(drag=>drag.index===index),position=pointGeometry(point,index,time,reduced,dragging,w,h),button=buttons[index],pan=pointPan(point),note=midiLabel(notes[index]);button.classList.toggle('low',position.y>.65);button.style.left=position.x*w+'px';button.style.top=position.y*h+'px';button.style.setProperty('--dot-size',(7+Math.min(1,level)*4*(.76+.24*Math.sin(Math.PI*2*(time*.019+index*.23))))+'px');button.dataset.x=point.x.toFixed(4);button.dataset.y=point.y.toFixed(4);button.dataset.note=note;button.dataset.pan=pan.toFixed(3);const label='Voice '+(index+1)+', '+note+', '+(Math.abs(pan)<.05?'center':Math.round(Math.abs(pan)*100)+'% '+(pan<0?'left':'right'))+'. Drag or use arrow keys; Home resets.';if(button.getAttribute('aria-label')!==label)button.setAttribute('aria-label',label);button.querySelector('.ambient-point-note').textContent=(index+1)+' · '+note;return position;});}
 return {render};
}
